(() => {
 const F=FRTB,U=FRTB_UI,{slider,select,bars,m,n,pct,green,lime,amber}=U,L=FRTB_LESSONS;
 const sample=(seed,count=250)=>{const r=SC.rng(seed);return Array.from({length:count},()=>SC.normal(r));},z=sample(81),noise=sample(913),series=(name,data,color)=>({name,data,color}),steps=a=>{const s=[...a].sort((a,b)=>a-b);return s.flatMap((v,i)=>[[v,i/s.length],[v,(i+1)/s.length]])};
 L.push({id:'var-es',name:'VaR and expected shortfall',stage:'05 · Internal models',title:'How bad are the days beyond the threshold?',intro:'VaR marks a loss threshold. Expected shortfall averages the tail beyond it. FRTB IMA uses 97.5% ES for market-risk capital and retains VaR for backtesting.',chart:'Sorted synthetic losses and their tail',inputs:[slider('scale','Ordinary loss scale',.5,10,.5,3),slider('tail','Extra loss on worst five scenarios',0,40,1,8),select('confidence','Explore tail threshold',[['0.975','97.5% · FRTB ES level'],['0.99','99% · compare with VaR tests']],'0.975')],challenge:'Increase only the worst five losses. Can ES move while the VaR threshold stays almost unchanged?',formula:'VaRα = α-quantile of losses\nESα = average loss in the worst (1 − α) fraction',key:'Positive numbers are losses. The empirical ES calculation allocates fractional mass at the tail boundary.',simpleTitle:'A fence versus what lies beyond it',simple:'VaR tells you where the unusually bad days begin. It does not describe how severe those days become. ES answers that second question by looking inside the tail.',scope:'250 equal-probability synthetic 10-day loss scenarios, held fixed as you change controls. This illustrates the statistic; it is not a complete FRTB calibration, liquidity adjustment or capital charge.',pages:[[245,'325bc · 97.5% partial ES'],[260,'325bf · one-day VaR backtesting']],compute(s){const a=z.map(v=>v*s.scale).sort((a,b)=>a-b).map((v,i)=>v+(i>=245?s.tail:0)),alpha=+s.confidence,t=F.tail(a,alpha),boundary=Math.ceil(alpha*250);return {stats:[['VaR',m(t.var)],['ES',m(t.es)],['Tail mass',n(250*(1-alpha))+' scenarios']],series:[series('Sorted loss',a.map((v,i)=>[i+1,v]),green),series('VaR threshold',[[1,t.var],[250,t.var]],amber),series('Expected shortfall',[[1,t.es],[250,t.es]],'#7e9f55')],xlabel:'Scenario rank, smallest to largest loss',headers:['Quantity','Value','Interpretation'],rows:[['Scenario count','250','Equal probability'],['Confidence',pct(alpha),'Threshold percentile'],['VaR order statistic',String(boundary),'Nearest-rank empirical quantile'],['Tail mass',n(250*(1-alpha)),'Fractional boundary scenario included in ES'],['VaR',m(t.var),'Loss threshold'],['ES',m(t.es),'Weighted average of the worst tail']],explanation:`At ${pct(alpha)} confidence, VaR is ${m(t.var)} and ES is ${m(t.es)}. ES reacts directly to the severity of the worst outcomes. These are loss measures at the stated horizon, not promises that losses cannot exceed them.`,note:'Changing confidence is a comparison exercise. Prescribed FRTB partial ES remains at 97.5%.'};}});
 L.push({id:'liquidity',name:'Liquidity horizons',stage:'05 · Internal models',title:'Some risks take longer to exit',intro:'The same market shock is more dangerous when a position cannot be hedged or exited quickly. FRTB uses five liquidity horizons.',chart:'Contributions to liquidity-adjusted ES',inputs:[slider('base','All-factor 10-day ES',1,50,1,15),slider('h20','ES with only LH ≥ 20 factors shocked',0,50,1,12),slider('h40','ES with only LH ≥ 40 factors shocked',0,50,1,9),slider('h60','ES with only LH ≥ 60 factors shocked',0,50,1,6),slider('h120','ES with only LH ≥ 120 factors shocked',0,50,1,3)],challenge:'Leave the all-factor ES unchanged and raise the 120-day subset. Why is its contribution amplified?',formula:'PES = √[ES10² + ES≥20² × 1 + ES≥40² × 2 + ES≥60² × 2 + ES≥120² × 6]',key:'The increments are (20−10)/10, (40−20)/10, (60−40)/10 and (120−60)/10. Each subset ES is itself measured on 10-day shocks.',simpleTitle:'Risk does not stop while you look for a buyer',simple:'Longer-horizon factors stay exposed after faster ones could have been hedged. The calculation adds incremental holding-time contributions, rather than scaling the entire portfolio to its slowest factor.',scope:'The sliders are separately calculated subset ES inputs. Factors outside each subset are held fixed. Subset ES need not decrease monotonically: removing a hedge can increase risk. The app does not infer these values from trades.',pages:[[245,'325bc · liquidity aggregation'],[249,'325bd · mapping and effective horizon'],[251,'325bdx · factor mapping']],reference:{headers:['Risk factor','Prescribed LH (days)'],rows:[['GIRR · liquid / domestic currency','10'],['GIRR · other currency','20'],['GIRR · volatility / other','60'],['CSR · IG sovereign','20'],['CSR · HY sovereign / IG corporate','40'],['CSR · HY corporate','60'],['CSR · volatility / other','120'],['Equity · large-cap spot','10'],['Equity · small-cap spot / large-cap volatility','20'],['Equity · small-cap volatility / other','60'],['FX · liquid pairs','10'],['FX · other pairs','20'],['FX · volatility / other','40'],['Commodity · energy / carbon / precious / non-ferrous prices','20'],['Commodity · other prices; energy / metal volatility','60'],['Commodity · other volatility / other types','120']]},notes:[['Maturity can limit the effective horizon','For position maturity below 10 days, effective LH is 10. Between 10 and 120 days, take the smaller of the subcategory LH and the next listed horizon at or above maturity. Beyond 120 days, use the subcategory LH. Longer desk-level subcategory horizons can be elected with notification.'],['Mapping is a risk decision','Choose the most appropriate category and subcategory for the risk factor. Ambiguity is resolved toward the longer applicable horizon. Homogeneous indices have a weighted-constituent mapping rule. Review mapping at least quarterly.']],compute(s){const raw=[s.base,s.h20,s.h40,s.h60,s.h120],weights=[1,1,2,2,6],contrib=raw.map((v,i)=>v*Math.sqrt(weights[i])),value=F.lh(s.base,raw.slice(1));return {stats:[['Liquidity-adjusted ES',m(value)],['Unadjusted 10-day ES',m(s.base)],['Horizons','10 → 120 days']],bars:bars(['All factors','LH ≥ 20','LH ≥ 40','LH ≥ 60','LH ≥ 120'],contrib),headers:['10-day scenario subset','ES input','Time weight','Squared contribution'],rows:raw.map((v,i)=>[['All factors','LH ≥ 20','LH ≥ 40','LH ≥ 60','LH ≥ 120'][i],m(v),String(weights[i]),n(v*v*weights[i])+' £m²']),explanation:`The root of the summed squared contributions is ${m(value)}. The 120-day subset contributes ${n(6*s.h120*s.h120)} £m² because the last horizon adds 60 days beyond the 60-day layer.`,note:'Bars show time-scaled ES contributions. Their squares are summed; the bars themselves are not added.'};}});
 L.push({id:'stress',name:'Stress calibration and reduced set',stage:'05 · Internal models',title:'Bring today’s portfolio into a stressed world',intro:'A reduced set with reliable history connects current risk to a severe historical period. Full and reduced-set ES are calculated under comparable conditions.',chart:'Three ES inputs and the stress-scaled result',inputs:[slider('fc','Full set · current PES (FC)',1,100,1,40),slider('rc','Reduced set · current PES (RC)',1,100,1,32),slider('rs','Reduced set · stressed PES (RS)',1,150,1,60),slider('coverage','60-day average of daily RC / FC ratios',0,120,1,80,'%')],challenge:'Make reduced-set current ES larger than full-set current ES. Does the stress scaling fall below one?',formula:'UES = PESRS × max(PESFC / PESRC, 1)\nReduced-set coverage: average of 60 daily (PESRC / PESFC) ratios ≥ 75%',key:'F = full modellable set; R = reduced modellable set; C = current period; S = stress period. PES already includes liquidity adjustment.',simpleTitle:'Use a reliable bridge back to stress',simple:'Not every present-day risk factor has a long, usable history. A representative reduced set provides that bridge. The full/current-to-reduced/current ratio adjusts for risks absent from the reduced set.',scope:'PES inputs are supplied rather than estimated from market history. The 60-day coverage average is a separate input: it is not inferred from today’s RC/FC ratio. A zero RC would require escalation rather than division; the slider excludes it.',pages:[[243,'325bb · unconstrained ES'],[246,'325bc(2) · reduced-set coverage'],[247,'325bc · stressed and current windows']],notes:[['Which stress period?','Choose a continuous 12-month period maximising reduced-set stressed PES, searching history starting at least on 1 January 2007. Reassess at quarterly reporting dates. Class-restricted measures use that same selected stress period.'],['What does the 75% test measure?','It is the average of the daily RC/FC ratios over 60 business days, not the ratio of two averages and not simply today’s ratio. Failure requires immediate PRA notification and an update of the reduced set within one month. Continued failure leads to excluding enough desks from IMA and applying SA to restore compliance.'],['Current calibration','Current data generally cover the preceding twelve months. A significant volatility upsurge in material full-set factors outside the reduced set requires a shorter window of at least six months. Current reduced-set data must be updated at least monthly.']],compute(s){const ratio=Math.max(s.fc/s.rc,1),value=F.ues(s.rs,s.fc,s.rc);return {stats:[['Unconstrained ES',m(value)],['Scaling ratio',n(ratio)+'×'],['Coverage test',s.coverage>=75?'Pass':'Below 75%']],bars:bars(['Full current','Reduced current','Reduced stress','UES'],[s.fc,s.rc,s.rs,value]),headers:['Step','Result','Meaning'],rows:[['FC / RC',n(s.fc/s.rc),'Current portfolio expansion factor'],['Floored ratio',n(ratio),'Never below one'],['RS × floored ratio',m(value),'Stress-scaled unconstrained ES'],['Today RC / FC',pct(s.rc/s.fc),'One observation; not the coverage test'],['60-day average coverage',s.coverage+'%',s.coverage>=75?'Meets minimum':'Notify and update reduced set']],explanation:`UES is ${m(s.rs)} × ${n(ratio)} = ${m(value)}. ${s.fc<s.rc?'The one-floor prevents a reduced/current ratio greater than full/current risk from reducing the stressed measure.':''} The separate 60-day coverage result ${s.coverage>=75?'meets':'fails'} the 75% requirement.`,note:'Passing coverage does not by itself establish sound data, RFET eligibility or supervisory permission.'};}});
 L.push({id:'constrained',name:'Constrained and unconstrained ES',stage:'05 · Internal models',title:'How much diversification should capital recognise?',intro:'IMA blends the whole-portfolio unconstrained ES with the sum of five class-restricted unconstrained ES measures.',chart:'Full diversification versus the prescribed blend',inputs:[slider('ir','Interest-rate UES',0,100,1,30),slider('credit','Credit-spread UES',0,100,1,40),slider('equity','Equity UES',0,100,1,20),slider('commodity','Commodity UES',0,100,1,15),slider('fx','FX UES',0,100,1,10),slider('benefit','Illustrative cross-class diversification',0,80,1,30,'%')],challenge:'Increase the diversification benefit. Why does the prescribed ES fall more slowly than unconstrained ES?',formula:'ES = 0.5 × UESportfolio + 0.5 × Σi UESi',key:'Five IMA categories: rates, credit spreads, equities, commodities and FX. Each UES is independently stress-scaled using its own FC, RC and RS measures.',simpleTitle:'A hedge across markets may weaken during stress',simple:'The whole-portfolio model can recognise relationships across markets. The class-restricted sum asks what risk remains when that cross-class diversification is removed. The fixed 50:50 blend limits reliance on that benefit.',scope:'The diversification slider constructs an illustrative portfolio UES from the class sum. It is not a prescribed correlation formula and is not a full joint-loss simulation. The 50% weight, however, is prescribed and cannot be changed.',pages:[[243,'325bb · portfolio and class-restricted ES'],[272,'325bh(2) · empirical correlations']],compute(s){const values=[s.ir,s.credit,s.equity,s.commodity,s.fx],total=F.sum(values),ues=total*(1-s.benefit/100),es=.5*(ues+total);return {stats:[['Blended ES',m(es)],['Portfolio UES',m(ues)],['Class-restricted sum',m(total)]],bars:bars(['Portfolio UES','Class sum','Blended ES'],[ues,total,es]),headers:['Component','UES','Contribution to blend'],rows:values.map((v,i)=>[['Interest rate','Credit spread','Equity','Commodity','FX'][i],m(v),m(.5*v)]).concat([['Whole portfolio',m(ues),m(.5*ues)],['Total ES','—',m(es)]]),explanation:`Full cross-class modelling produces ${m(ues)} in this illustration. The prescribed blend is ${m(es)}, halfway between that and the ${m(total)} class sum. Only half the assumed cross-class diversification benefit enters this ES measure.`,note:'“Constrained ES” here refers to the prescribed diversification blend; the article labels the final measure ES.'};}});
 L.push({id:'rfet',name:'RFET · real-price evidence',stage:'06 · Model eligibility and data',title:'Is there enough observable price evidence?',intro:'The risk factor eligibility test asks whether a factor is sufficiently supported by verifiable, representative prices with distinct observation dates.',chart:'Where the observed prices fall during a year',inputs:[slider('count','Candidate price observations',0,150,1,30,'observations'),slider('gap','Unobserved days at end of year',0,270,5,0,'days'),select('verifiable','Price evidence',[['yes','Verifiable and representative'],['no','Indicative / unverifiable only']],'yes')],challenge:'Keep thirty observations but cluster them early in the year. Then try the 100-date route.',formula:'Modellable by count if:\n(≥ 24 distinct dates AND ≥ 4 prices in every 90-day window) OR ≥ 100 distinct dates',key:'Assessment uses a 12-month period ending at the preceding quarterly reference date, subject to the permitted consistent one-month shift.',simpleTitle:'A full spreadsheet can still hide a long silence',simple:'Thirty prices from one busy week do not tell you much about the rest of a year. The first route checks both the total and the continuity of evidence. The alternative 100-date route provides another way to meet the count test.',scope:'A synthetic 365-day year with observations distributed across the selected active interval. The rolling test scans every contained 90-day window. Actual implementation must use dated records, correct year length, common time zone, representative mapping and the prescribed curve/surface buckets.',pages:[[253,'325be · count and continuity'],[254,'325be · verifiable prices'],[256,'325be(8) · bucket eligibility']],notes:[['What counts as a real price?','Arm’s-length transactions or bona fide competitive bid and offer quotations with a commitment to execute can qualify. Indicative quotes, same-group transactions, negligible sizes, off-market quotes and trades made solely to pass the test do not qualify. Only distinct observation dates count.'],['The evidence trail','Third-party data require the specified vendor processing, evidence availability, mapping information and independent annual audit arrangements. Record transaction execution dates or committed quote dates in a consistent time zone. A price can represent more than one factor only with documented, validated justification and PRA notification.'],['Curves, surfaces and cubes','Assess the prescribed maturity and moneyness buckets rather than arbitrarily sharing observations across a surface. Bespoke buckets require the stated conditions. Retain at least a year of assessment results when available. Passing RFET is necessary but data-input quality remains a separate requirement.']],compute(s){const span=365-s.gap,days=Array.from({length:s.count},(_,i)=>Math.floor((i+.5)*span/Math.max(s.count,1))),r=F.rfet(s.verifiable==='yes'?days:[]),monthly=Array.from({length:12},(_,i)=>days.filter(d=>Math.floor(d/365*12)===i).length);return {stats:[['Count test',r.pass?'Pass':'Fail'],['Eligible distinct dates',String(r.count)],['Least in any 90 days',String(r.min90)]],bars:bars(Array.from({length:12},(_,i)=>'Month '+(i+1)),monthly),headers:['Test','Observed','Result'],rows:[['Verifiable and representative',s.verifiable==='yes'?'Yes':'No',s.verifiable==='yes'?'Count eligible dates':'Candidate prices excluded'],['Distinct dates',String(r.count),'At most one per date'],['24-date route',r.count+' dates; minimum '+r.min90+' / 90 days',r.route24?'Pass':'Fail'],['100-date route',String(r.count),r.route100?'Pass':'Fail'],['Overall count eligibility','Either route',r.pass?'Pass; assess remaining data requirements':'NMRF treatment required']],explanation:`${r.count} eligible distinct dates support this factor. ${r.pass?(r.route24?'The 24-date plus continuity route passes.':'The 100-date route passes even though the continuity route fails.'):'Neither route passes; the factor cannot enter modellable ES on this evidence.'} RFET does not certify the quality of the time series used for shocks.`,note:'Bars show candidate observations by month, including excluded evidence. Eligibility statistics count only accepted prices.'};}});
 L.push({id:'data',name:'Data principles and proxies',stage:'06 · Model eligibility and data',title:'Observable does not always mean usable',intro:'A factor may pass RFET while its model history still understates risk. Compare a market series with a smoothed model input.',chart:'How smoothing can erase risk',inputs:[slider('smooth','Input smoothing',0,95,5,40,'%'),slider('basis','Uncaptured name-specific risk',0,5,.25,1),select('response','Response to detected understatement',[['none','No adjustment'],['adjust','Adjust inputs to restore observed variation'],['nmrf','Move the affected factor to NMRF treatment']],'none')],challenge:'Increase smoothing until the model series looks reassuring. What evidence would justify that reassurance?',formula:'RFET evidence + suitable model inputs + consistent valuation data\nA count-test pass does not override Article 325bh data-quality requirements.',key:'The chart demonstrates information loss. The smoothing slider and illustrative ES estimates are not regulatory data-quality pass/fail thresholds.',simpleTitle:'Cleaning noise can accidentally clean away risk',simple:'Data transformations can make a series look stable without making the underlying position safer. FRTB requires the model inputs to preserve relevant volatility, correlations and both systematic and idiosyncratic risks.',scope:'Synthetic 250-day changes. Model inputs shrink market variation and omit a name-specific component; the adjustment option restores the observed changes for this example. Real remediation needs documented analysis and validation.',pages:[[272,'325bh(3–4) · data eligibility'],[273,'325bh(5–9) · comparison principles'],[274,'325bh(10–14) · updates, stress data and proxies']],notes:[['Seven practical checks','1. Build inputs from modellable factors under the interpolation/extrapolation rules. 2. Capture systematic and idiosyncratic risk. 3. Preserve volatility and correlation. 4. Compare risk-model, valuation, verifiable and independent-price-verification series. 5. Review and escalate differences that understate ES. 6. Keep data and regression parameters sufficiently current. 7. Justify stress-history construction and proxies. These group the article’s requirements for learning; they are not an alternative rulebook.'],['What comparison is required?','At least quarterly, compare levels, volatilities and correlations across the four price sources; account for overlap, price uncertainty and available intraday information. Review and escalate results. Remedies include adjusting inputs or outputs, or classifying affected factors as non-modellable.'],['Update cadence','Model data are generally updated at least weekly; justified cases may be monthly. Regression parameters are generally re-estimated at least fortnightly; a slower frequency requires justification and specification in permission. Document gap filling, backfilling and alternative-source workflows.'],['Proxies and PLAT','Proxies must be conceptually and empirically sound. Use the same proxy, interpolation or permitted extrapolation in risk-theoretical P&L. Using the actual factor instead requires identifying and adequately capitalising the proxy basis. Stress data for new factors need empirical justification; an easy proxy is not automatically acceptable.']],compute(s){const actual=z.map((v,i)=>3*v+s.basis*noise[i]),raw=z.map(v=>3*v*(1-s.smooth/100)),model=s.response==='adjust'?actual:raw,ae=F.tail(actual,.975).es,me=F.tail(model,.975).es;return {stats:[['Observed illustrative ES',m(ae)],['Model-input ES',m(me)],['Factor route',s.response==='nmrf'?'NMRF':'Review data']],series:[series('Observed changes',actual.map((v,i)=>[i+1,v]),green),series('Model inputs',model.map((v,i)=>[i+1,v]),amber)],xlabel:'Synthetic observation day',headers:['Check','Example outcome','Required reasoning'],rows:[['RFET','Assumed pass','Separate from input suitability'],['Variation retained',(100-s.smooth)+'% before remediation','Does transformation preserve risk?'],['Name-specific component',s.basis?'Present in observed series':'None in this example','Is idiosyncratic risk captured?'],['Illustrative ES gap',m(ae-me),'Investigate, not a regulatory tolerance'],['Selected action',s.response,'Document and validate the actual remedy']],explanation:`The model-input ES is ${m(me)} against ${m(ae)} using the observed synthetic changes. ${s.response==='nmrf'?'The affected factor moves to stress-scenario treatment; its risk does not disappear.':s.response==='adjust'?'Restoring the observed series removes this example’s smoothing and omitted-factor gap.':'Lower measured risk here comes from missing variation, not a safer position.'}`,note:'ES in this data-quality illustration is calculated from one-day changes; it is not the liquidity-adjusted capital measure.'};}});
 L.push({id:'nmrf',name:'NMRFs and stress scenarios',stage:'06 · Model eligibility and data',title:'Unmodellable risk still needs capital',intro:'NMRFs leave modellable ES and receive a stress scenario risk measure (SSRM). First stress the factor, then scale and aggregate.',chart:'Standalone stress and aggregation',inputs:[slider('credit','Idiosyncratic credit · 10-day stress ES',0,30,1,5),slider('equity','Idiosyncratic equity · 10-day stress ES',0,30,1,4),slider('a','Other factor A · 10-day stress ES',0,30,1,8),slider('b','Other factor B · 10-day stress ES',0,30,1,6),select('lh','Assigned liquidity horizon',[['10','10 days'],['20','20 days'],['40','40 days'],['60','60 days'],['120','120 days']],'60')],challenge:'Change the horizon from ten to twenty days. Why does the stress-scaling factor stay unchanged?',formula:'SSj = SSj(10) × √[max(20, LHj) / 10]\nSStotal = √ΣICSR SS² + √ΣIEQ SS² + √[(0.6 ΣOR SS)² + 0.64 ΣOR SS²]',key:'Idiosyncratic credit and equity sets require the article’s strict independence conditions. The other-risk aggregate uses ρ = 0.6 in the displayed formula.',simpleTitle:'Less evidence calls for a different risk treatment',simple:'A thinly observed risk factor is not a zero-risk factor. Its charge asks what a severe standalone shock could do, then recognises only the prescribed aggregation benefits.',scope:'Four nonnegative standalone stress ES inputs share the selected LH. One qualifies as purely idiosyncratic credit, one as purely idiosyncratic equity, and two are other risks. Real qualification and stress selection require evidence; these labels are assumptions.',pages:[[278,'325bk · standalone stress and scaling'],[281,'325bk · stress period and fallback'],[282,'325bk(13–15) · aggregation']],notes:[['Stress construction','The factor’s standalone measure must be at least as conservative as 97.5% stressed ES with a 10-day base horizon, scaled to at least 20 days. Methodologies, any proxies and bucketing need documented rationale and validation. A permitted common bucket shock must account for basis risk.'],['Finding stress when history is thin','Select a stress period using history beginning at least in 2007 and review at least quarterly. If an acceptable extreme shock cannot be developed, Article 325bk specifies a conservative regulatory fallback using a 99.95% 10-day shock and historical maximum up/down losses, then the same horizon scaling. This app illustrates the ordinary standalone-ES route, not the fallback calibration.'],['Idiosyncratic is a substantive claim','The separate credit and equity square-root sums require no systematic driver, negligible correlations, no materially correlated subsets and documented statistical tests. Relabelling a systematic factor to obtain diversification is not allowed.']],compute(s){const k=Math.sqrt(Math.max(20,+s.lh)/10),v=[s.credit,s.equity,s.a,s.b].map(x=>x*k),total=F.nmrf([v[0]],[v[1]],v.slice(2)),other=F.nmrf([],[],v.slice(2));return {stats:[['Aggregate SSRM',m(total)],['Horizon scaling',n(k)+'×'],['Minimum horizon','20 days']],bars:bars(['Idio credit','Idio equity','Other A','Other B','Aggregate'],[...v,total]),headers:['Component','10-day stress ES','Scaled SS','Aggregation'],rows:[['Idiosyncratic credit',m(s.credit),m(v[0]),'Separate credit root-sum-square'],['Idiosyncratic equity',m(s.equity),m(v[1]),'Separate equity root-sum-square'],['Other A',m(s.a),m(v[2]),'Other-risk formula'],['Other B',m(s.b),m(v[3]),'Other-risk formula'],['Other-risk aggregate','—',m(other),'ρ = 0.6, 1 − ρ² = 0.64'],['Total SSRM','—',m(total),'Sum the three group charges']],explanation:`Standalone stress losses are multiplied by ${n(k)}. The two other risks combine to ${m(other)} under the prescribed formula, and total SSRM is ${m(total)}. The minimum 20-day horizon remains even for a factor assigned a 10-day LH.`,note:'SSRM is added to ES in IMA capital; NMRFs also remain relevant to desk backtesting and risk-theoretical P&L.'};}});
 L.push({id:'plat',name:'PLAT · explain the P&L',stage:'07 · Desk tests',title:'Does the risk model tell the same P&L story?',intro:'P&L attribution compares hypothetical P&L from valuation with risk-theoretical P&L from the risk model. Rank agreement and distribution agreement are different tests.',chart:'Hypothetical and risk-theoretical P&L distributions',inputs:[slider('noise','Unexplained P&L noise',0,1.5,.05,.3,'×'),slider('bias','Risk-model P&L bias',-1,1,.02,0,'£m'),select('previous','Previous quarter’s capital approach',[['ima','IMA'],['sa','Standardised approach']],'ima')],challenge:'Add a constant bias with no noise. Can ranks still match while the distribution test deteriorates?',formula:'Spearman r = correlation(rank(HPL), rank(RTPL))\nKS = maxx |CDFHPL(x) − CDFRTPL(x)|',key:'Green: r > 0.8 AND KS < 0.09. Red: r < 0.7 OR KS > 0.12. Otherwise orange if previous quarter used SA, yellow otherwise.',simpleTitle:'Same ordering does not mean the same losses',simple:'A risk model could rank every day correctly but systematically understate the size of the moves. Spearman examines co-movement in ranks; the KS distance checks whether the two P&L distributions have drifted apart.',scope:'250 paired synthetic daily observations, with a fixed sample. Quarterly steady-state PLAT logic from this PRA instrument. The 2028 deemed-green transitional treatment is covered in the final lesson.',pages:[[266,'325bg · P&L attribution'],[267,'325bg(5–6) · Spearman and KS'],[269,'325bg(7) · four zones']],notes:[['HPL, RTPL and APL','HPL freezes positions and revalues with the valuation/pricing framework. RTPL also freezes positions but uses the risk model’s pricing methods, parameters and risk factors, including those capitalised through SSRM. APL reflects actual portfolio changes, with the prescribed exclusions. PLAT compares HPL to RTPL; backtesting uses HPL and APL.'],['Four zones in this PRA text','Green is eligible subject to the other requirements. Yellow attracts a portfolio surcharge. Orange and red desks use SA. Orange captures an intermediate-scoring desk that used SA in the previous quarter; merely moving out of red is insufficient to re-enter IMA. The strict inequalities mean equality at 0.8/0.09 or 0.7/0.12 is intermediate unless the other metric triggers red.'],['Method and alignment','Use the most recent 250 business days. Snapshot and data alignment are permitted only within Article 325bg’s conditions. For ties, this implementation follows paragraph 5(d) literally: lower-observation count + 1, plus 1 / tie-count when tied. That differs from the conventional average-rank rule; the synthetic sample normally has no ties.']],compute(s){const h=z,rt=h.map((v,i)=>v+s.noise*noise[i]+s.bias),r=F.correlation(F.ranks(h),F.ranks(rt)),k=F.ks(h,rt),zone=F.platZone(r,k,s.previous==='sa');return {stats:[['PLAT zone',zone],['Spearman r',n(r)],['KS distance',n(k)]],series:[series('HPL cumulative distribution',steps(h),green),series('RTPL cumulative distribution',steps(rt),amber)],y:[0,1],xlabel:'Daily P&L (£m); vertical axis = cumulative probability',headers:['Test','Measured','Steady-state interpretation'],rows:[['Spearman rank correlation',n(r),r>.8?'Meets green rank criterion':r<.7?'Triggers red':'Intermediate rank score'],['KS distribution distance',n(k),k<.09?'Meets green distribution criterion':k>.12?'Triggers red':'Intermediate distribution score'],['Previous quarter',s.previous.toUpperCase(),'Determines orange versus yellow in intermediate range'],['Combined zone',zone,zone==='Green'?'Eligible if all other requirements hold':zone==='Yellow'?'IMA with surcharge':'SA required']],explanation:`The desk is ${zone.toLowerCase()}: rank correlation is ${n(r)} and KS distance is ${n(k)}. ${s.noise===0&&s.bias!==0?'A constant bias preserves ranks but moves the distribution.':''} ${zone==='Orange'?'Because the previous quarter used SA, intermediate results do not restore IMA.':''}`,note:'The curves are empirical CDFs. The largest vertical gap is KS; the source uses strict thresholds.'};}});
 L.push({id:'backtest',name:'Backtesting and multipliers',stage:'07 · Desk tests',title:'How often does loss cross the forecast?',intro:'Desk-level backtesting controls eligibility. A separate portfolio-level test determines the ES multiplier. Both compare forecasts with realised P&L.',chart:'Synthetic HPL losses crossing one-day 99% VaR',inputs:[slider('h99','Desk · HPL 99% breaches',0,40,1,5,'days'),slider('a99','Desk · APL 99% breaches',0,40,1,7,'days'),slider('hExtra','Desk · extra HPL 97.5% breaches',0,30,1,7,'days'),slider('aExtra','Desk · extra APL 97.5% breaches',0,30,1,8,'days'),slider('firmH','Portfolio · HPL 99% breaches',0,15,1,5,'days'),slider('firmA','Portfolio · APL 99% breaches',0,15,1,6,'days')],challenge:'Set a desk to twelve 99% breaches, then thirteen. Separately change the portfolio breach count from four to five.',formula:'Desk passes if HPL99 ≤ 12, APL99 ≤ 12, HPL97.5 ≤ 30, APL97.5 ≤ 30\nmc = 1.5 + add-on(max(portfolio HPL99 breaches, portfolio APL99 breaches))',key:'Each count uses the most recent 250 business days. The desk test includes NMRFs; the portfolio multiplier test shocks modellable risk factors.',simpleTitle:'A forecast must face the days that actually happened',simple:'Occasional exceptions are expected from a probabilistic forecast. Persistent exceptions can signal missing risk. FRTB uses separate thresholds for whether a desk can use its model and how much conservatism the portfolio ES needs.',scope:'Breach counts are direct inputs. The chart constructs 250 synthetic losses matching the desk HPL 99% count; it is not an independent statistical estimate. Additional 97.5% breaches ensure its count cannot be below the 99% count.',pages:[[260,'325bf · desk thresholds'],[261,'325bf · portfolio multiplier'],[262,'325bf · add-on table']],reference:{headers:['Portfolio 99% breaches','Add-on','mc'],rows:[[0,'0','1.50'],['1–4','0','1.50'],[5,'.20','1.70'],[6,'.26','1.76'],[7,'.33','1.83'],[8,'.38','1.88'],[9,'.42','1.92'],['10+','.50','2.00']]},notes:[['HPL and APL are complementary','HPL asks how yesterday’s unchanged positions performed. APL reflects actual changes, excluding fees and commissions and with the article’s valuation-adjustment treatment. Test both; one cannot substitute for the other. A day with missing valuation or VaR is counted as an overshooting.'],['Two scopes, two consequences','Desk backtesting at both 99% and 97.5% includes risk factors identified through PLAT, including NMRFs. The firm portfolio multiplier uses 99% VaR on modellable risk factors and takes the greater HPL/APL count. Do not apply the firm add-on table as the desk eligibility test.'],['Escalation and exceptions','Notify the PRA promptly of breaches, no later than five business days, and explain them. Exclusion from the portfolio count requires PRA permission under the specified conditions; an analyst cannot simply delete an inconvenient exception.']],compute(s){const h975=s.h99+s.hExtra,a975=s.a99+s.aExtra,pass=s.h99<=12&&s.a99<=12&&h975<=30&&a975<=30,firm=Math.max(s.firmH,s.firmA),mc=F.multiplier(firm),loss=Array.from({length:250},(_,i)=>[((i*73)%250)+1,i<s.h99?1.15+Math.abs(z[i])*.3:.1+.7*Math.abs(Math.sin(i*2.31))]).sort((a,b)=>a[0]-b[0]);return {stats:[['Desk test',pass?'Pass':'Fail'],['Portfolio mc',n(mc)+'×'],['Portfolio count',String(firm)]],series:[series('Synthetic HPL loss',loss,green),series('One-day 99% VaR',[[1,1],[250,1]],amber)],xlabel:'Business day; losses in illustrative £m',headers:['Test','Breaches','Limit / use'],rows:[['Desk HPL 99%',s.h99,'≤ 12'],['Desk APL 99%',s.a99,'≤ 12'],['Desk HPL 97.5%',h975,'≤ 30'],['Desk APL 97.5%',a975,'≤ 30'],['Portfolio max HPL/APL 99%',firm,'Add-on '+n(mc-1.5)],['ES multiplication factor',n(mc),'Base 1.5 + portfolio add-on']],explanation:`The desk ${pass?'passes':'fails'} the four count thresholds. Separately, ${firm} portfolio exceptions produce mc = ${n(mc)}. ${pass?'A pass still needs the required track record, PLAT and other permissions.':'A firm multiplier cannot cure a failed desk eligibility test.'}`,note:'This chart shows only HPL at 99%; the table contains the remaining tests and independent portfolio scope.'};}});
 // Deterministic conditional independent-default distribution. This is deliberately not presented as a complete regulatory default model.
 function defaultDistribution(pd,rho){const bins=Array(21).fill(0),steps=400;for(let i=0;i<steps;i++){const zz=-7+14*(i+.5)/steps,weight=Math.exp(-zz*zz/2)/Math.sqrt(2*Math.PI)*14/steps;let lo=-9,hi=9;for(let j=0;j<45;j++){const mid=(lo+hi)/2;if(SC.cdf(mid)<pd)lo=mid;else hi=mid}const threshold=(lo+hi)/2,p=SC.cdf((threshold-Math.sqrt(rho)*zz)/Math.sqrt(1-rho));SC.binomial(20,p).forEach((v,k)=>bins[k]+=weight*v);}const mass=F.sum(bins);return bins.map(v=>v/mass);}
 L.push({id:'ima-drc',name:'IMA default-risk model',stage:'08 · Capital and governance',title:'Defaults can arrive together',intro:'IMA default capital is a separate 99.9% one-year loss quantile. Dependence matters because a cluster of defaults can overwhelm diversification.',chart:'Probability of simultaneous defaults',inputs:[slider('pd','Annual probability of default',0,10,.01,1,'%'),slider('rho','Illustrative systematic dependence',0,80,5,20,'%'),slider('lgd','Loss given default',0,100,5,60,'%'),slider('notional','Total portfolio face value',0,200,5,100)],challenge:'Hold PD and LGD fixed while raising dependence. Compare average loss with the 99.9% tail.',formula:'Internal default-risk measure = VaR99.9%(one-year default losses)\nCapital default component = max(latest measure, preceding 12-week average)',key:'PD floor = 0.03%; LGD floor = 0%. Defaults are incremental to losses already included in current valuations.',simpleTitle:'The average is not the catastrophe',simple:'Twenty issuers can have the same individual default probability whether they fail independently or during the same downturn. Dependence changes the chance of many losses arriving together, even when expected loss stays the same.',scope:'A teaching-only one-factor Gaussian mixture with twenty equal par-valued debt exposures, fixed LGD and one-year constant positions. Numerical integration supplies the default-count distribution. It does NOT satisfy the full PRA internal default model requirements, including two types of systematic factors, calibrated recovery dependence and instrument-level basis risk.',pages:[[283,'325bl–bm · scope and permission'],[284,'325bn · 99.9% default loss'],[285,'325bo–bp · hedges and model requirements'],[286,'325bp · PD and LGD']],notes:[['What a real model must add','Model individual and simultaneous issuer defaults with two types of systematic risk factors, economic-cycle and recovery dependence, nonlinear instruments and relevant basis risks. Correlations need objective historical data covering at least ten years including the selected stress period. Calculate the measure at least weekly.'],['PD and hedge requirements','PD uses at least five years of past-default or equivalent extreme-decline data and cannot be inferred solely from current market prices. Use one-year PD, subject to the stated equity horizon derogation. Model gross long and short positions when recognising cross-instrument or cross-issuer hedges, including maturity and seniority mismatches.'],['Scope restrictions','Debt and equity default risk is incremental to ES/SSRM. Failing default-model requirements can move the entire desk to SA. Article 325bm(3) also requires SA default treatment for specified exposures even within IMA; this toy corporate portfolio does not represent those exceptions.']],compute(s){const pd=Math.max(.0003,s.pd/100),dist=defaultDistribution(pd,s.rho/100);let cumulative=0,k=20;for(let i=0;i<dist.length;i++){cumulative+=dist[i];if(cumulative>=.999){k=i;break}}const unit=s.notional/20*s.lgd/100,capital=k*unit,el=20*pd*unit;return {stats:[['Toy 99.9% default VaR',m(capital)],['Expected loss',m(el)],['Effective PD',pct(pd)]],bars:dist.map((v,i)=>({label:i+' defaults',value:100*v,color:i>=k?amber:green})),headers:['Quantity','Value','Interpretation'],rows:[['Issuer count','20','Equal exposures'],['Effective PD',pct(pd),'0.03% floor applied'],['Expected defaults',n(20*pd),'Same marginal PD at every correlation'],['99.9% default-count quantile',k,'Discrete distribution'],['Loss per default',m(unit),'Exposure / 20 × LGD'],['Toy default VaR',m(capital),'Count quantile × loss per default']],explanation:`Average default loss is ${m(el)}, while this simplified model’s 99.9% loss quantile is ${m(capital)}. The tail changes in steps because there are only twenty equal exposures. Dependence changes clustering, not the marginal PD entered here.`,note:'Bars are probabilities (%). This is a default-dependence illustration, not a regulatory-compliant internal DRC model.'};}});
 L.push({id:'capital',name:'IMA capital assembly',stage:'08 · Capital and governance',title:'Put the IMA pieces together',intro:'Combine ES, non-modellable stress risk, default risk, yellow-desk surcharges and SA fallback using the PRA’s aggregation.',chart:'From IMA measures to total market-risk capital',inputs:[slider('es','Previous-day ES',0,100,1,30),slider('ss','Previous-day SSRM',0,50,1,8),slider('esAvg','60-day average ES',0,100,1,25),slider('ssAvg','60-day average SSRM',0,50,1,7),slider('breaches','Portfolio backtesting exceptions',0,15,1,4,'days'),slider('drc','Latest DRC',0,50,1,6),slider('drcAvg','12-week average DRC',0,50,1,7),slider('sagy','SA for green/yellow portfolio',0,200,1,70),slider('yellow','Yellow share of summed desk SA',0,100,5,20,'%'),slider('cu','SA fallback portfolio (CU)',0,100,1,15),slider('all','SA for all desks together',0,250,1,80)],challenge:'Raise IMA above the green/yellow SA benchmark. Why is total capital not simply capped at all-desk SA?',formula:'IMA = max(ESyesterday + SSyesterday, mc × ES60avg + SS60avg) + max(DRClatest, DRC12weekavg)\nSurcharge = 0.5 × yellow share × max(SAg&y − IMA, 0)\nTotal = min(IMA + surcharge + CU, SAall) + max(IMA − SAg&y, 0)',key:'Yellow share is Σ individual yellow-desk SA / Σ individual green-and-yellow-desk SA. SAg&y is instead SA calculated on their combined portfolio.',simpleTitle:'Today’s quiet reading cannot erase recent risk',simple:'A maximum against recent averages prevents capital from collapsing after a single calm day. Desk quality then affects the route to capital: yellow desks add a surcharge, while ineligible, orange, red or failed desks contribute through SA.',scope:'Inputs are already-calculated portfolio measures. IMA refers to the eligible green/yellow portfolio; CU and the two SA benchmarks must be independently calculated at their stated scopes. The sliders do not enforce consistency with an actual trade population. This shows steady-state Article 325ba, excluding institution-specific additional risk-capture charges.',pages:[[241,'325ba(1–3) · maxima and capital'],[242,'325ba(3–5) · surcharge and total']],compute(s){const mc=F.multiplier(s.breaches),today=s.es+s.ss,avg=mc*s.esAvg+s.ssAvg,defaultCharge=Math.max(s.drc,s.drcAvg),ima=Math.max(today,avg)+defaultCharge,k=.5*s.yellow/100,surcharge=k*Math.max(s.sagy-ima,0),a=Math.min(ima+surcharge+s.cu,s.all),b=Math.max(ima-s.sagy,0),total=a+b;return {stats:[['Total capital',m(total)],['IMA component',m(ima)],['Yellow surcharge',m(surcharge)]],bars:bars(['IMA eligible','Surcharge','CU · SA','Total'],[ima,surcharge,s.cu,total]),headers:['Calculation','Result','Rule'],rows:[['Yesterday ES + SS',m(today),'Daily branch'],['mc × average ES + average SS',m(avg),'mc = '+n(mc)],['ES / SS capital',m(Math.max(today,avg)),'Larger branch'],['Default capital',m(defaultCharge),'Latest versus 12-week average'],['IMAg&y',m(ima),'Market-risk plus default components'],['Yellow coefficient k',n(k),'0.5 × '+s.yellow+'%'],['Yellow surcharge',m(surcharge),'k × max(SAg&y − IMAg&y, 0)'],['Formula (a)',m(a),'min(IMA + surcharge + CU, SAall)'],['Formula (b)',m(b),'max(IMA − SAg&y, 0)'],['Total',m(total),'Formula (a) + formula (b)']],explanation:`Total capital is ${m(total)}. The ES/SS branch uses ${today>=avg?'yesterday’s sum':'the multiplier-adjusted 60-day average'}, and DRC contributes ${m(defaultCharge)}. ${b>0?'The second term preserves the excess of IMA over its green/yellow SA benchmark, so SAall is not an unconditional cap.':'The IMA-over-SA excess term is zero at these inputs.'}`,note:'These are market-risk own-funds calculations, not the separate institution-wide output-floor calculation.'};}});
 L.push({id:'governance',name:'Boundary, permission and transition',stage:'08 · Capital and governance',title:'A model is part of a controlled process',intro:'The trading-book boundary, desk permissions, validation and implementation dates determine where the calculations apply.',chart:'An illustrative desk’s route',inputs:[select('year','Regime',[['2027','2027 · IMA transitional permission'],['2028','2028 · FRTB IMA deemed-green year'],['steady','Steady-state FRTB IMA']],'steady'),select('permission','Relevant desk/model permission',[['yes','Granted; other scope conditions met'],['no','Not granted']],'yes'),select('eligible','Position scope',[['yes','Eligible for IMA'],['no','Ineligible position, e.g. securitisation']],'yes'),select('backtest','Required desk backtesting record',[['yes','Meets requirements'],['no','Fails requirements']],'yes'),select('zone','Measured PLAT zone',[['Green','Green'],['Yellow','Yellow'],['Orange','Orange'],['Red','Red']],'Green')],challenge:'Compare a red measured PLAT result in steady state and in the 2028 deemed-green year. Which other checks remain?',formula:'Scope and permission → eligible position → desk tests → model / SA route\nGovernance and validation remain necessary throughout.',key:'This is a decision illustration, not an application for permission or a complete legal eligibility determination.',simpleTitle:'Capital rules need a stable perimeter',simple:'If positions could move freely between books or desks whenever one formula looked cheaper, the framework would lose meaning. FRTB combines calculation rules with documented trading intent, desk organisation and supervised model use.',scope:'The route assumes no exceptional PRA waiver and treats other requirements as satisfied unless a control says otherwise. Ineligible positions are carved out to SA. The 2027 transitional framework has separate legacy model rules and is not calculated by the ES applets.',pages:[[238,'Chapter 4 · IMA transitionals'],[239,'325az · desk permission and deficiencies'],[275,'325bi–bj · governance and validation'],[293,'Annex 3 · transitional IMA']],notes:[['Trading-book boundary and desk organisation','The Trading Book Part governs classification, trading intent, documented management and restrictions on transfers. A trading desk has a defined business strategy, risk limits, responsible traders and management oversight. An accounting label alone is not a full FRTB boundary decision. Banking-book FX and commodity risks are also within the market-risk scope specified by the general provisions.'],['Permission and ineligible positions','IMA permission is desk-based and tied to the model and its standards. Securitisations, resecuritisations, ACTP and certain non-look-through CIUs are ineligible positions under this instrument and are treated separately using SA. Material changes/extensions need permission; other changes require the prescribed notifications.'],['2027 and 2028 are not steady state','The instrument defines an IMA transitional period from 1 January to 31 December 2027. Annex 3 supplies transitional internal-model rules, including VaR, stressed VaR and the applicable additional charges. Chapter 4.1 treats IMA-permitted desks as green for one year after that period (2028) for Article 325ba capital and relaxes the stated application standard. This does not switch off all other requirements. These applets’ PLAT consequences and ES capital assembly otherwise show steady-state FRTB logic.'],['Validation goes beyond two tests','Independent validation must examine assumptions, basis risk, concentration, proxy behaviour and hypothetical portfolios, not just PLAT and backtesting. Independent risk control reports to senior management. Perform rigorous stress and reverse-stress testing, review results at least monthly and review the overall risk-management process at least annually.'],['Other parts of the framework','Keep track of valuation adjustments, model risk and material deficiencies in risk capture, the standardised fallback, internal default-model scope and change control. FRTB market-risk capital is distinct from counterparty credit risk, CVA capital, credit-risk capital and the institution-wide output floor; a full bank capital implementation needs those separate modules.']],compute(s){let route,reason;if(s.permission==='no'){route='SA';reason='The relevant permission is missing.'}else if(s.eligible==='no'){route='SA carve-out';reason='Ineligible positions are treated separately from the IMA desk.'}else if(s.year==='2027'){route='Transitional IMA';reason='Apply the Annex 3 permission and legacy model rules; these ES/PLAT controls do not determine that regime.'}else if(s.backtest==='no'){route='SA fallback';reason='The required desk backtesting record fails; deemed-green PLAT status does not cure it.'}else {const effective=s.year==='2028'?'Green':s.zone;route=effective==='Green'?'IMA':effective==='Yellow'?'IMA + surcharge':'SA fallback';reason=s.year==='2028'?'Chapter 4.1 deems the permitted desk green for capital during 2028.':effective+' PLAT consequences apply, subject to the remaining requirements.'}return {stats:[['Illustrative route',route],['Regime',s.year==='steady'?'Steady state':s.year],['Measured PLAT',s.zone]],bars:bars(['Permission','Eligible scope','Backtest record'],[s.permission==='yes'?1:0,s.eligible==='yes'?1:0,s.backtest==='yes'?1:0]),headers:['Gate','Selected condition','Meaning'],rows:[['Permission',s.permission,'Necessary, not sufficient'],['Position eligibility',s.eligible,'Ineligible positions carved out to SA'],['Regime',s.year,'Dates determine applicable rules'],['Backtesting',s.backtest,'Separate from PLAT'],['Measured PLAT',s.zone,s.year==='2028'?'Deemed green for 2028 capital':s.year==='2027'?'Not the transitional Annex 3 test':'Steady-state zone'],['Illustrative route',route,reason]],explanation:reason+' Independent validation, data integrity and ongoing risk management are still part of the framework.',note:'Bars show selected conditions (1 = met, 0 = not met), not a score that can establish regulatory permission.'};}});
})();
